    { w: "follow in someone's footsteps", ar: "يسير على خطى أحد", pos: "idiom", def: "to do the same job or live the same way as someone before you", ex: "Nadia followed in her mother's footsteps and became a pharmacist.", tag: "life stages & generations" },
    { w: "millennial", ar: "من جيل الألفية", pos: "noun", def: "a person born roughly between the early 1980s and the mid-1990s", ex: "My cousin is a millennial, so she remembers life before smartphones.", tag: "life stages & generations" },
    { w: "label", ar: "يصنّف / يلصق وصفاً بشخص", pos: "verb", def: "to describe someone with one word or category, often unfairly", ex: "Teenagers dislike being labelled as lazy just because they enjoy sleeping late.", tag: "life stages & generations" },
    { w: "social butterfly", ar: "شخص اجتماعي كثير المعارف والمناسبات", pos: "idiom", def: "a person who enjoys moving between social events and talking to everyone", ex: "Rania is a real social butterfly; she seems to know someone at every wedding.", tag: "sociable vs solitary traits" },
    { w: "gregarious", ar: "اجتماعي يحب الاختلاط", pos: "adjective", def: "enjoying the company of other people", ex: "A gregarious person may find a quiet weekend at home rather dull.", tag: "sociable vs solitary traits" },
    { w: "extrovert", ar: "انبساطي", pos: "noun / adjective", def: "a lively, confident person who gains energy from being with others", ex: "As an extrovert, Hamza feels most alive when he is talking to a large group.", tag: "sociable vs solitary traits" },
    { w: "loner", ar: "انعزالي / يفضّل الوحدة", pos: "noun", def: "a person who prefers to be alone", ex: "Some people call him a loner, but he simply enjoys long walks by himself.", tag: "sociable vs solitary traits" },
    { w: "introspective", ar: "ميّال إلى التأمل الذاتي", pos: "adjective", def: "tending to examine your own thoughts and feelings carefully", ex: "After the argument, Dina became quiet and introspective for a few days.", tag: "sociable vs solitary traits" },
    { w: "reserved", ar: "متحفّظ قليل البوح بمشاعره", pos: "adjective", def: "slow to show your feelings or opinions to other people", ex: "Though reserved in class, Omar is very funny with his close friends.", tag: "sociable vs solitary traits" },
    { w: "stand-offish", ar: "جافٍ ومتباعد", pos: "adjective", def: "cold and unfriendly towards other people", ex: "She isn't stand-offish; she is just shy and needs time to relax with new people.", tag: "sociable vs solitary traits" },
    { w: "anxiety", ar: "القلق", pos: "noun", def: "a feeling of worry or fear about something that might happen", ex: "Speaking in front of a crowd fills many people with anxiety.", tag: "wellbeing" },
    { w: "contentment", ar: "القناعة والرضا", pos: "noun", def: "a calm feeling of being happy with what you have", ex: "She found contentment in simple things: a quiet cup of tea and a good book.", tag: "wellbeing" },
    { w: "isolation", ar: "العزلة غير المرغوبة", pos: "noun", def: "the state of being separated from other people", ex: "Long periods of isolation can leave people feeling low and disconnected.", tag: "wellbeing" },
    { w: "endorphins", ar: "الإندورفين: مواد طبيعية ترفع المزاج", pos: "noun", def: "natural chemicals in the brain that reduce pain and improve mood", ex: "Laughing with friends may release endorphins, which help us feel relaxed and cheerful.", tag: "wellbeing" },
    { w: "colour symbolism", ar: "رمزية الألوان", pos: "noun", def: "the meanings that cultures link to particular colours", ex: "Colour symbolism varies: white suggests purity in some cultures but mourning in others.", tag: "clothing, identity & culture" },
    { w: "dress code", ar: "قواعد اللباس المطلوبة", pos: "noun", def: "a set of rules about what people must or should wear", ex: "The restaurant has a smart dress code, so shorts and trainers are not allowed.", tag: "clothing, identity & culture" },
    { w: "peer pressure", ar: "ضغط الأقران", pos: "noun", def: "the strong influence of people your own age on what you do", ex: "Peer pressure can push young people to buy things they do not really need.", tag: "clothing, identity & culture" },
    { w: "conform", ar: "يتماشى مع السائد / يمتثل", pos: "verb", def: "to behave or dress in the way most people around you do", ex: "Some teenagers conform to fashion trends because they fear standing out.", tag: "clothing, identity & culture" }
